    static Map<String,JsonObject> catalog(GenericRecipes<GenericRecipe> h)throws Exception{h.deleteRecipes();h.registerDefaults();Map<String,JsonObject> rows=new LinkedHashMap<>();for(var r:h.recipeOrderedList){StringWriter s=new StringWriter();try(JsonWriter w=new JsonWriter(s)){w.beginObject();h.writeRecipe(r,w);w.endObject();}rows.put(r.name,JsonParser.parseString(s.toString()).getAsJsonObject());}return rows;}
